const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '点A' },
      { kind: 'text', payload: '点B' },
      { kind: 'text', payload: '点C' },
      { kind: 'text', payload: '边AB' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;

    var Ax = 0.14 * w, Ay = 0.80 * h;
    var Bx = 0.86 * w, By = 0.80 * h;
    var Cx = 0.50 * w, Cy = 0.22 * h;

    var fs = Math.max(12, Math.min(18, h * 0.045));
    var dotR = Math.max(2.5, Math.min(4.5, h * 0.011));
    var dy = 0.085 * h;
    var dx = 0.045 * w;

    var sideAB = visualSdk.polyline([[Ax, Ay], [Bx, By]]);
    var sideBC = visualSdk.polyline([[Bx, By], [Cx, Cy]]);
    var sideCA = visualSdk.polyline([[Cx, Cy], [Ax, Ay]]);

    var dotA = visualSdk.circle(Ax, Ay, dotR);
    var dotB = visualSdk.circle(Bx, By, dotR);
    var dotC = visualSdk.circle(Cx, Cy, dotR);

    var paths = [
      { id: 'sideAB', commands: sideAB },
      { id: 'sideBC', commands: sideBC },
      { id: 'sideCA', commands: sideCA },
      { id: 'dotA', commands: dotA },
      { id: 'dotB', commands: dotB },
      { id: 'dotC', commands: dotC }
    ];

    var ink = '#1f2937';

    var labels = [
      { type: 'label', text: '点A', x: Ax - dx, y: Ay + dy, fontSize: fs, fill: ink, align: 'center', baseline: 'middle' },
      { type: 'label', text: '点B', x: Bx + dx, y: By + dy, fontSize: fs, fill: ink, align: 'center', baseline: 'middle' },
      { type: 'label', text: '点C', x: Cx, y: Cy - dy, fontSize: fs, fill: ink, align: 'center', baseline: 'middle' },
      { type: 'label', text: '边AB', x: 0.5 * w, y: Ay - 0.075 * h, fontSize: fs, fill: ink, align: 'center', baseline: 'middle' }
    ];

    return {
      schemaVersion: 1,
      sceneId: 'triangle-abc-figure',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: paths,
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'sideBC', stroke: ink, strokeWidth: 1.6, fill: 'none' },
          { type: 'path', pathId: 'sideCA', stroke: ink, strokeWidth: 1.6, fill: 'none' },
          { type: 'path', pathId: 'sideAB', stroke: ink, strokeWidth: 2.6, fill: 'none' },
          { type: 'path', pathId: 'dotA', stroke: ink, strokeWidth: 1.2, fill: ink },
          { type: 'path', pathId: 'dotB', stroke: ink, strokeWidth: 1.2, fill: ink },
          { type: 'path', pathId: 'dotC', stroke: ink, strokeWidth: 1.2, fill: ink }
        ].concat(labels)
      }
    };
  }
};
